import sys
sys.path.insert(0, sys.argv[1])
from service import save
from store import Store, ReceiptUnavailable

def run(name, fn):
    try: print(name, "->", fn())
    except Exception as e: print(name, "-> EXC", type(e).__name__, e)

def fresh_id():
    s = Store(); save(s, "w", "op-1", {"c": "blue"})
    r = save(s, "w", "op-2", {"c": "red"})
    return r, s.preferences["w"], sorted(s.recovery)
def edited_retry_after_apply():
    s = Store(); s.fail_receipt_once = True
    try: save(s, "w", "op-1", {"c": "blue"})
    except ReceiptUnavailable: pass
    r = save(s, "w", "op-1", {"c": "red"})
    return r, s.preferences["w"], s.recovery["op-1"]
def reuse_id_other_ws():
    s = Store(); save(s, "a", "op-1", {"c": "blue"})
    save(s, "b", "op-1", {"c": "red"})
    return s.recovery
def completed_repeat_receipt_down():
    s = Store(); save(s, "w", "op-1", {"c": "blue"})
    s.fail_receipt_once = True
    return save(s, "w", "op-1", {"c": "blue"})
for n, f in [("fresh_id", fresh_id), ("edited_retry_after_apply", edited_retry_after_apply),
             ("reuse_id_other_ws", reuse_id_other_ws), ("completed_repeat_receipt_down", completed_repeat_receipt_down)]:
    run(n, f)
EOF
